-- Incremental local migration. Legacy records remain unclassified; never aggregate legacy votes.
CREATE TABLE IF NOT EXISTS el_users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), username text UNIQUE NOT NULL, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('admin','analyst')), active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS el_sessions(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES el_users(id),expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS el_types(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,key text UNIQUE NOT NULL,description text,origin text NOT NULL,status text NOT NULL DEFAULT 'confirmed',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS el_solutions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),procedure text NOT NULL,author text,origin text NOT NULL,status text NOT NULL DEFAULT 'active',legacy_id uuid UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS el_links(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),solution_id uuid NOT NULL REFERENCES el_solutions(id),type_id uuid NOT NULL REFERENCES el_types(id),UNIQUE(solution_id,type_id));
CREATE TABLE IF NOT EXISTS el_occurrences(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),original_title text NOT NULL,type_id uuid REFERENCES el_types(id),status text NOT NULL DEFAULT 'pending',applied_solution_id uuid REFERENCES el_solutions(id),external_id text UNIQUE,received_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz,created_by uuid REFERENCES el_users(id));
CREATE TABLE IF NOT EXISTS el_sources(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),solution_id uuid NOT NULL REFERENCES el_solutions(id),source_key text UNIQUE NOT NULL,ticket_number text,article_id text,ticket_title text,author text,source_date text,content text NOT NULL,metadata jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS el_recommendations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),occurrence_id uuid NOT NULL REFERENCES el_occurrences(id),link_id uuid NOT NULL REFERENCES el_links(id),snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(occurrence_id,link_id));
CREATE TABLE IF NOT EXISTS el_evaluations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),occurrence_id uuid NOT NULL REFERENCES el_occurrences(id),link_id uuid NOT NULL REFERENCES el_links(id),positive boolean NOT NULL,comment text,user_id uuid NOT NULL REFERENCES el_users(id),attempt_key uuid UNIQUE NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS el_audit(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),occurrence_id uuid REFERENCES el_occurrences(id),user_id uuid REFERENCES el_users(id),action text NOT NULL,details jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS el_settings(key text PRIMARY KEY,value jsonb NOT NULL);
CREATE INDEX IF NOT EXISTS el_evaluations_link ON el_evaluations(link_id,created_at);
CREATE INDEX IF NOT EXISTS el_occurrences_type ON el_occurrences(type_id,received_at);
CREATE INDEX IF NOT EXISTS el_audit_occurrence ON el_audit(occurrence_id,created_at);
INSERT INTO el_solutions(id,procedure,author,origin,legacy_id,created_at) SELECT id,solucao,autor,origem,id,created_at FROM kb_solucoes ON CONFLICT DO NOTHING;
COMMENT ON TABLE kb_votos IS 'Legacy evaluations preserved; not used in event-type statistics because occurrence and classification cannot be established safely.';
